<?php require_once __DIR__.'/../includes/bootstrap.php';require_customer();$c=customer_row();$title='Personal Details';$msg='';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$phone=trim((string)($_POST['phone']??''));if($phone!==($c['phone']??'')){try{$pdo->prepare('UPDATE customers SET phone=?,updated_at=NOW() WHERE customer_id=?')->execute([$phone,(int)$c['customer_id']]);$msg='Phone number updated successfully.';$c=customer_row();}catch(Throwable $e){$errors[]='The phone number could not be updated.';}}else{$msg='Your permanent account details remain protected. No changes were required.';}}$title='Personal Details';require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">IDENTITY & PROFILE</span><h1>Personal details</h1><p>Your name, email and username are permanent registered identity details. Password changes are handled separately.</p></div></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($errors):?><div class="errors"><?=e($errors[0])?></div><?php endif;?><section class="panel"><div class="form two"><label>Full name<input value="<?=e($c['full_name'])?>" disabled></label><label>Username<input value="<?=e($c['username'])?>" disabled></label><label>Email<input value="<?=e($c['email'])?>" disabled></label><label>Phone<form method="post"><?=csrf_field()?><input name="phone" value="<?=e($c['phone']??'')?>"><button class="btn primary" style="margin-top:8px">Update phone</button></form></label></div></section><?php require __DIR__.'/../includes/footer.php';?>